"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["90654"],{77338(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.fonte_valores_fora_de_categorico","status":422,"titulo":"S\xf3 fato categ\xf3rico declara a fonte dos seus valores"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.fonte_valores_fora_de_categorico","requisitos":["UNI-REQ-0143","UNI-REQ-0159"],"oQueAconteceu":["A fonte dos valores diz de onde v\xeam as op\xe7\xf5es de um fato categ\xf3rico, que \xe9 escolhido numa lista. Os outros tipos de dado n\xe3o t\xeam op\xe7\xf5es (UNI-REQ-0143). O cadastro de um fato declarado (`POST /api/configuracao/admin/fatos-candidato`) ou a altera\xe7\xe3o da defini\xe7\xe3o (`PUT /api/configuracao/admin/fatos-candidato/{id}/definicao`) de um fato declarado trouxe uma `fonteValores` junto de um `dominio` que n\xe3o \xe9 `OPCAO`.","A recusa vem na lista `errors` da resposta, com `field` igual a `fonteValores`. Ela s\xf3 \xe9 dada quando o dom\xednio \xe9 v\xe1lido. Nada \xe9 gravado. O fato derivado por regra e o resumo de grupo n\xe3o informam a fonte: quem a envia na altera\xe7\xe3o recebe [a recusa de eixo que o tipo do fato n\xe3o permite alterar](/erros/uniplus.configuracao.fato_candidato.eixo_nao_editavel_no_tipo_do_fato)."],"comoResolver":["Retire a `fonteValores` do corpo, ou mude o `dominio` para `OPCAO` se o fato \xe9 mesmo uma lista de op\xe7\xf5es."],"ondeAparece":["Cadastro de um fato declarado do cat\xe1logo","Altera\xe7\xe3o da defini\xe7\xe3o de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);